The issue is that the method `TestMax` body got separated from its declaration. The closing brace block at the end needs to be attached to `TestMax`.

@@ method TestMax(a: int, b: int) @@
+ {
+   var result := Max(a, b);
+   assert result == a || result == b;
+   assert result >= a && result >= b;
+ }
@@ method TestMaxAlgebra(a: int, b: int, c: int) @@
- {
-  MaxCommutative(a, b);
-  assert Max(a, b) == Max(b, a);
-  assert Max(a, a) == a;
-  assert Max(Max(a, b), c) == Max(a, Max(b, c));
- }
- 
- {
-   var result := Max(a, b);
-   assert result == a || result == b;
-   assert result >= a && result >= b;
- }
+ {
+  MaxCommutative(a, b);
+  assert Max(a, b) == Max(b, a);
+  assert Max(a, a) == a;
+  assert Max(Max(a, b), c) == Max(a, Max(b, c));
+ }
